&lt;ul style=&quot;margin-top:2px&quot;&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Acad&#233;mie-Des-Grands-Arts-(Barde).html&quot; title=&quot;Royaumes ind&#233;pendants: Acad&#233;mie des Grands arts&quot;&gt;Acad&#233;mie des Grands arts&lt;/a&gt; (CSU)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#194;me-En-Peine-(Barde).html&quot; title=&quot;&#194;me en peine&quot;&gt;&#194;me en peine&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Arch&#233;ologue-(Barde).html&quot; title=&quot;Arch&#233;ologue&quot;&gt;Arch&#233;ologue&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Archiviste-(Barde).html&quot; title=&quot;Archiviste&quot;&gt;Archiviste&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Artiste-Des-Rues-(Barde).html&quot; title=&quot;Artiste des rues&quot;&gt;Artiste des rues&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Artiste-Masqu&#233;-(Barde).html&quot; title=&quot;Artiste masqu&#233;&quot;&gt;Artiste masqu&#233;&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Barde-De-Cour-(Barde).html&quot; title=&quot;Barde de cour&quot;&gt;Barde de cour&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Barde-Fun&#232;bre-(Barde).html&quot; title=&quot;Barde fun&#232;bre&quot;&gt;Barde fun&#232;bre&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Boucanier-(Barde).html&quot; title=&quot;Boucanier&quot;&gt;Boucanier&lt;/a&gt; (PMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Casse-Cou-(Barde).html&quot; title=&quot;Casse-cou&quot;&gt;Casse cou&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;C&#233;l&#233;brit&#233;-(Barde).html&quot; title=&quot;C&#233;l&#233;brit&#233;&quot;&gt;C&#233;l&#233;brit&#233;&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chantemer-(Barde).html&quot; title=&quot;Chantemer&quot;&gt;Chantemer&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chanteur-De-Leau-(Barde).html&quot; title=&quot;Chanteur de l’eau&quot;&gt;Chanteur de l&#39;eau&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Ondin-(Race).html&quot; title=&quot;Les ondins&quot;&gt;Ondin&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Danseur-Des-Flammes-(Barde).html&quot; title=&quot;Danseur des flammes&quot;&gt;Danseur des flammes&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;magogue-(Barde).html&quot; title=&quot;D&#233;magogue&quot;&gt;D&#233;magogue&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Derviche-(Barde).html&quot; title=&quot;Derviche&quot;&gt;Derviche&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Derviche-De-La-Fleur-De-Laube-(Barde).html&quot; title=&quot;Derviche de l&amp;#39;aube (barde)&quot;&gt;Derviche de l&#39;aube&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tective-(Barde).html&quot; title=&quot;D&#233;tective&quot;&gt;D&#233;tective&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Diva-Ch&#233;liaxienne-(Barde).html&quot; title=&quot;Diva&quot;&gt;Diva&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dragon-Jappeur-(Barde).html&quot; title=&quot;Dragon jappeur&quot;&gt;Dragon jappeur&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Kobold-(Race).html&quot; title=&quot;Les kobolds&quot;&gt;Kobold&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Duelliste-Des-Arcanes-(Barde).html&quot; title=&quot;Duelliste des arcanes&quot;&gt;Duelliste des arcanes&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Farceur-(Barde).html&quot; title=&quot;Farceur&quot;&gt;Farceur&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Gnome.html&quot; title=&quot;Les gnomes&quot;&gt;Gnome&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Frappeson-(Barde).html&quot; title=&quot;Frappeson&quot;&gt;Frappeson&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Geisha-(Barde).html&quot; title=&quot;Geisha&quot;&gt;Geisha&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Intellectuel-(Barde).html&quot; title=&quot;Intellectuel&quot;&gt;Intellectuel&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Interpr&#232;te-De-Ballades-Argent&#233;es-(Barde).html&quot; title=&quot;Interpr&#232;te de ballades argent&#233;es&quot;&gt;Interpr&#232;te de ballades argent&#233;es&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Marchand-De-Sable-(Barde).html&quot; title=&quot;Marchand de sable&quot;&gt;Marchand de sable&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Marionnettiste-Des-Ombres-(Barde).html&quot; title=&quot;Marionnettiste des ombres&quot;&gt;Marionnettiste des ombres&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Wayang-(Race).html&quot; title=&quot;Les wayangs&quot;&gt;Wayang&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Meneur-(Barde).html&quot; title=&quot;Meneur&quot;&gt;Meneur&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Messager-Inflexible-(Barde).html&quot; title=&quot;Messager inflexible&quot;&gt;Messager inflexible&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Orateur-Animal-(Barde).html&quot; title=&quot;Orateur animal&quot;&gt;Orateur animal&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Phr&#233;nologue-(Barde).html&quot; title=&quot;Phr&#233;nologue&quot;&gt;Phr&#233;nologue&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Prestidigitateur-(Barde).html&quot; title=&quot;Prestidigitateur&quot;&gt;Prestidigitateur&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Scalde-Sauvage-(Barde).html&quot; title=&quot;Scalde sauvage&quot;&gt;Scalde sauvage&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Soignechant-(Barde).html&quot; title=&quot;Soignechant&quot;&gt;Soignechant&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Voix-De-La-Nature-(Barde).html&quot; title=&quot;Voix de la nature&quot;&gt;Voix de la nature&lt;/a&gt; (MCA)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des joueurs - R&#232;gles avanc&#233;es (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Player&#39;s Guide/Manuel des joueurs - R&#232;gles avanc&#233;es&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAPG.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;i&gt;Certains bardes pr&#233;f&#232;rent de loin les &#233;tudes au drame (et parfois au m&#233;lodrame) pris&#233; par leurs fr&#232;res artistes. &lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Repr&#233;sentations bardiques&lt;a class=&quot;headeranchor&quot; id=&quot;Repr&#233;sentations_bardiques_0&quot; href=&quot;#Repr&#233;sentations_bardiques_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un archiviste ma&#238;trise les types de &lt;a class=&quot;pagelink&quot; href=&quot;Barde#Representationbardique.html&quot; title=&quot;repr&#233;sentation bardique&quot;&gt;repr&#233;sentation bardique&lt;/a&gt; suivants.&lt;br /&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;i&gt;Naturaliste (Ext).&lt;/i&gt; Un archiviste &#233;tant parvenu &#224; identifier une cr&#233;ature gr&#226;ce &#224; un test de &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;connaissance&lt;/a&gt; appropri&#233; peut durant le combat partager avec ses compagnons des tactiques visant &#224; la vaincre. Lui et les alli&#233;s situ&#233;s dans un rayon de 9 m&#232;tres (6 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;) b&#233;n&#233;ficient d’un bonus d’intuition de +1 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt;, aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt; et aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jets de sauvegarde&lt;/a&gt; contre les capacit&#233;s exceptionnelles et surnaturelles et contre les pouvoirs magiques utilis&#233;s par les cr&#233;atures d’un certain type (par exemple les g&#233;ants du froid, et non tous les g&#233;ants ou tous les humano&#239;des). Ce bonus augmente de +1 au niveau 5 et par tranche de six niveaux au-del&#224;. Cette aptitude d&#233;pend du langage, poss&#232;de une &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts.html#Les composantes&quot; title=&quot;Pr&#233;sentation des sorts&quot;&gt;composante sonore et visuelle&lt;/a&gt; et remplace &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentations.html#Inspiration_vaillante&quot; title=&quot;Les repr&#233;sentations bardiques du barde&quot;&gt;inspiration vaillante&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;i&gt;Lamentable injure (Ext).&lt;/i&gt; Au niveau 6, le personnage peut d&#233;concentrer une cr&#233;ature d&#233;j&#224; fascin&#233;e par sa repr&#233;sentation. Utiliser cette aptitude n’interrompt pas la &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentations.html#Fascination_Sur_2&quot; title=&quot;Les repr&#233;sentations bardiques du barde&quot;&gt;fascination&lt;/a&gt;, mais son activation n&#233;cessite une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;, en plus de l’&lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Libre.html&quot; title=&quot;Action libre&quot;&gt;action libre&lt;/a&gt; permettant de prolonger la &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentations.html#Fascination_Sur_2&quot; title=&quot;Les repr&#233;sentations bardiques du barde&quot;&gt;fascination&lt;/a&gt;. La cible doit effectuer un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;Volont&#233;&lt;/a&gt; (DD 10 + la moiti&#233; du niveau de barde + son modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt;) et si elle le r&#233;ussit, elle sera immunis&#233;e &#224; ce pouvoir durant 24 heures. Si elle &#233;choue, elle sera &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#H&#233;b&#233;t&#233;.html&quot; title=&quot;H&#233;b&#233;t&#233;&quot;&gt;h&#233;b&#233;t&#233;e&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Confus.html&quot; title=&quot;Confus&quot;&gt;confuse&lt;/a&gt; (au choix de l’archiviste) aussi longtemps que le barde poursuivra sa repr&#233;sentation ou jusqu’&#224; ce qu’elle subisse des dommages. Cette aptitude affectant l’esprit poss&#232;de une composante sonore et remplace &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentations.html#suggestion_Mag_5&quot; title=&quot;Les repr&#233;sentations bardiques du barde&quot;&gt;suggestion&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;i&gt;Lecture p&#233;dante (Sur).&lt;/i&gt; Au niveau 18, un archiviste peut affecter &#224; l’aide de &lt;i&gt;lamentable injure&lt;/i&gt; autant de cr&#233;atures qu’il en a &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Fascin&#233;.html&quot; title=&quot;Fascin&#233;&quot;&gt;fascin&#233;es&lt;/a&gt;. De plus, il peut choisir de les faire dormir plut&#244;t que de les rendre &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Confus.html&quot; title=&quot;Confus&quot;&gt;confuses&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#&#201;bloui.html&quot; title=&quot;&#201;bloui&quot;&gt;&#233;blouies&lt;/a&gt;. Cette aptitude remplace &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentations.html#Suggestion_de_groupe_Mag_11&quot; title=&quot;Les repr&#233;sentations bardiques du barde&quot;&gt;suggestion de groupe&lt;/a&gt;&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Ma&#238;tre du savoir (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Ma&#238;tre_du_savoir_Ext_1&quot; href=&quot;#Ma&#238;tre_du_savoir_Ext_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 2 un archiviste peut d&#233;cider de &lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences.html#Faire_BA_ou_faire_CA_0&quot; title=&quot;Les comp&#233;tences&quot;&gt;faire 20&lt;/a&gt; sur un test de &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; une fois par jour plus une fois tous les six niveaux au-del&#224; du niveau 2. Cette aptitude remplace &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Barde#Versatiliteartistique.html&quot; title=&quot;Versatilit&#233; artistique&quot;&gt;versatilit&#233; artistique&lt;/a&gt;&lt;/i&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Savoir magique (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Savoir_magique_Ext_2&quot; href=&quot;#Savoir_magique_Ext_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 2, l’archiviste b&#233;n&#233;ficie d’un bonus sur ses tests d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Art-De-La-Magie.html&quot; title=&quot;Art de la magie&quot;&gt;Art de la magie&lt;/a&gt; lorsqu’il s’agit d’identifier des objets magiques ou de d&#233;chiffrer des parchemins &#233;gal &#224; la moiti&#233; de son niveau de barde et peut &#233;galement choisir de &lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences.html#Faire_BA_ou_faire_CA_0&quot; title=&quot;Les comp&#233;tences&quot;&gt;faire 10&lt;/a&gt; sur de tels tests. Il peut utiliser la comp&#233;tence &lt;a class=&quot;pagelink&quot; href=&quot;Sabotage.html&quot; title=&quot;Sabotage&quot;&gt;Sabotage&lt;/a&gt; pour neutraliser les pi&#232;ges magiques comme s’il poss&#233;dait l’aptitude de classe du roublard &lt;a class=&quot;pagelink&quot; href=&quot;Roublard.html#Recherche_des_pi&#232;ges&quot; title=&quot;Le roublard&quot;&gt;recherche de pi&#232;ges&lt;/a&gt;. Il gagne un bonus de +4 sur ses &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jets de sauvegarde&lt;/a&gt; contre les pi&#232;ges magiques et les effets d&#233;pendant du langage, ainsi que sur les symboles, les glyphes et les &#233;critures magiques de n’importe quel type. Cette aptitude remplace &lt;a class=&quot;pagelink&quot; href=&quot;Barde.html#&#201;rudition_Ext_6&quot; title=&quot;Le barde&quot;&gt;&#233;rudition&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;Touche &#224; tout (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Touche_&#224;_tout_Ext_3&quot; href=&quot;#Touche_&#224;_tout_Ext_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 5, l’archiviste peut utiliser n’importe quelle comp&#233;tence et ce m&#234;me si elle exige qu’il soit form&#233;. Au niveau 11, toutes les comp&#233;tences deviennent des comp&#233;tences de classe pour lui et au niveau 17, il peut choisir de &lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences.html#Faire_BA_ou_faire_CA_0&quot; title=&quot;Les comp&#233;tences&quot;&gt;faire 10&lt;/a&gt; sur n’importe quel &lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences.html#Tests_de_comp&#233;tences_2&quot; title=&quot;Les comp&#233;tences&quot;&gt;test de comp&#233;tence&lt;/a&gt; m&#234;me si cela n’est pas autoris&#233;. Cette aptitude remplace &lt;a class=&quot;pagelink&quot; href=&quot;Barde.html#Ma&#238;tre_du_savoir_Ext_7&quot; title=&quot;Le barde&quot;&gt;ma&#238;tre du savoir&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Chemin des possibles (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Chemin_des_possibles_Ext_4&quot; href=&quot;#Chemin_des_possibles_Ext_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 10, un archiviste peut d&#233;terminer l’action la moins risqu&#233;e et qui aura le plus de chances de r&#233;ussir. Il peut choisir de &#171; &lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences#Faire10.html&quot; title=&quot;faire 10&quot;&gt;faire 10&lt;/a&gt; &#187; sur n’importe quel jet utilisant un d20 une fois par jour, plus une fois par tranche de trois niveaux au-del&#224; du niveau 10. Cette aptitude remplace &lt;a class=&quot;pagelink&quot; href=&quot;Barde.html#TOUCHE-A-TOUT&quot; title=&quot;Le barde&quot;&gt;touche-&#224;-tout&lt;/a&gt; (du barde de base, niveau 10).
